"""The four modes' census lines are pinned: the DRY-RUN line, the ACTIVE line and every LEVER line of `exact` (S1), `fast` (LSTAR2A),
`big` (BIG_F) and `big --n_gpu 2` (BIG_TP, dry run) — rendered in this CPU process on the stub upstream exactly as test_activation
renders them — must equal RECORDED byte for byte; any difference is a census change and fails here before any GPU run sees it. `exact` and
`fast` are pinned twice: as shipped (no query: every lever bound) and below the small-input floor (smalln.py: a 200-token call, the trunk
levers composed out — `floor=below_gate:200/300`, LEVER `state=off reason=below_gate:200/300`).
Capture: KIT_LINES_OUT=<path> python -m pytest …/test_mode_lines_unchanged.py writes the current tree's lines as JSON instead of asserting."""
import json
import os

import pytest

from opendde_opt import big, modes, report, smalln, stack
from opendde_opt.tests.test_activation import fresh  # noqa: F401  (the fixture: stub upstream first on sys.path, clean switches, fresh activation state)

CASES = (("exact", 1, None), ("fast", 1, None), ("big", 1, None), ("big", 2, None), ("exact", 1, 200), ("fast", 1, 200))   # (mode, n_gpu, below: the residue tokens of a call below the small-input floor, or None = no query)


def _case_id(mode, n_gpu, below):
    return f"{mode}x{n_gpu}" + (f"_below{below}" if below else "")


def _render(mode, n_gpu, below=None):
    smalln._reset()
    if below:                                                                                    # what cli.pred does before activation: the floor's plan from the query's residue tokens
        smalln._ST["plan"] = {**smalln.policy(big.count_tokens([{"name": "q", "sequences": [{"proteinChain": {"sequence": "A" * below, "count": 1}}]}]), {}), "tokens": None}
        assert smalln._ST["plan"]["below"], smalln._ST["plan"]
    if n_gpu > 1:
        modes.MODE_LINES["big"] = modes.BIG_TP_LINE                                        # what a rank process does (tp.enter_rank_process): the mode word stays big
    try:
        dry = stack.activate(mode, dry_run=True, n_gpu=n_gpu)
    finally:
        modes.MODE_LINES["big"] = "BIG_F"
    out = {"dry": report.activation_line(dry), "active": None, "lever": None}
    if n_gpu == 1:                                                                               # the ×P line's real activation is the rank processes' (GPU); its dry run is the launcher's census
        stack._APPLIED.clear(); stack._REPORT = None
        rep = stack.activate(mode, n_gpu=n_gpu)
        assert rep["active"], rep.get("reason")
        out["active"] = report.activation_line(rep)
        out["lever"] = report.lever_lines(rep, stats={})
    smalln._reset()
    return out




@pytest.mark.parametrize("mode,n_gpu,below", CASES, ids=[_case_id(*c) for c in CASES])
def test_mode_census_lines_equal_the_landed_trees(fresh, monkeypatch, mode, n_gpu, below):
    for k in list(os.environ):
        if k.startswith(("OPENDDE_BIG_", "MODEL_OPT_BIG_", "MODEL_OPT_SMALL_")):           # the big lever flags / size gates / the small-input floor: none in force (the shipped values)
            monkeypatch.delenv(k)
    big._reset()
    got = _render(mode, n_gpu, below)
    cap = os.environ.get("KIT_LINES_OUT")
    if cap:                                                                                      # capture route: record this tree's lines
        cur = json.load(open(cap)) if os.path.exists(cap) else {}
        cur[_case_id(mode, n_gpu, below)] = got
        json.dump(cur, open(cap, "w"), indent=1, sort_keys=True)
        return
    want = RECORDED[_case_id(mode, n_gpu, below)]
    assert got["dry"] == want["dry"], (got["dry"], want["dry"])
    assert got["active"] == want["active"], (got["active"], want["active"])
    assert got["lever"] == want["lever"], "\n".join(f"- {a}\n+ {b}" for a, b in zip(want["lever"] or [], got["lever"] or []) if a != b) or (want["lever"], got["lever"])


